import sys
import math

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        K = int(input[ptr+1])
        ptr += 2
        if N == 1:
            print(1)
        else:
            if K % N == 0:
                print(K // N)
            else:
                print((K // N) + 1)

solve()
